package main

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"reflect"
	"strconv"
	"strings"
	"unicode"
)

var (
	EOF = errors.New("unexpected end of file")
)

type NodeType int

const (
	NodeNil NodeType = iota
	NodeT
	NodeInt
	NodeDouble
	NodeString
	NodeQuote
	NodeBquote
	NodeIdent
	NodeLambda
	NodeSpecial
	NodeBuiltinfunc
	NodeCell
	NodeArray
	NodeAref
	NodeEnv
	NodeError
	NodeGoValue
)

type Node struct {
	t   NodeType
	v   interface{}
	car *Node
	cdr *Node
}

func (n *Node) String() string {
	if n == nil {
		return "nil"
	}
	var buf bytes.Buffer
	switch n.t {
	case NodeArray:
		curr := n
		fmt.Fprint(&amp;buf, "[")
		for curr != nil {
			if curr.car != nil {
				fmt.Fprint(&amp;buf, curr.car)
			} else {
				fmt.Fprint(&amp;buf, "nil")
			}
			if curr.cdr == nil || curr.cdr.t == NodeNil {
				break
			}
			fmt.Fprint(&amp;buf, " ")
			curr = curr.cdr
		}
		fmt.Fprint(&amp;buf, "]")
	case NodeCell:
		curr := n
		fmt.Fprint(&amp;buf, "(")
		for curr != nil {
			if curr.car != nil {
				fmt.Fprint(&amp;buf, curr.car)
			} else {
				fmt.Fprint(&amp;buf, "nil")
			}
			if curr.cdr == nil || curr.cdr.t == NodeNil {
				break
			}
			if curr.cdr.t != NodeCell {
				fmt.Fprint(&amp;buf, " . ")
				fmt.Fprint(&amp;buf, curr.cdr)
				break
			}
			fmt.Fprint(&amp;buf, " ")
			curr = curr.cdr
		}
		fmt.Fprint(&amp;buf, ")")
	case NodeNil:
		fmt.Fprint(&amp;buf, "nil")
	case NodeT:
		fmt.Fprint(&amp;buf, "t")
	case NodeQuote:
		fmt.Fprintf(&amp;buf, "'%v", n.car)
	case NodeBquote:
		fmt.Fprintf(&amp;buf, "`%v", n.car)
	case NodeString:
		fmt.Fprintf(&amp;buf, "%q", n.v)
	case NodeLambda:
		fmt.Fprintf(&amp;buf, "(lambda %v %v)", n.car, n.cdr.car)
	case NodeEnv:
		if n.car != nil {
			fmt.Fprintf(&amp;buf, "(defun %v %v %v)", n.v, n.car, n.cdr.car)
		} else {
			fmt.Fprintf(&amp;buf, "(defun %v %v)", n.v, n.cdr.car)
		}
	case NodeGoValue:
		rv, ok := n.v.(reflect.Value)
		if ok {
			switch rv.Kind() {
			case reflect.String:
				fmt.Fprintf(&amp;buf, "%q", rv.Interface())
			default:
				fmt.Fprint(&amp;buf, rv.Interface())
			}
		}
	default:
		fmt.Fprint(&amp;buf, n.v)
	}
	return buf.String()
}

func NewParser(r io.Reader) *Parser {
	return &amp;Parser{
		buf: bufio.NewReader(r),
	}
}

type Parser struct {
	buf *bufio.Reader
	pos int
}

func (p *Parser) NewError(err error) *Node {
	return &amp;Node{
		t: NodeError,
		v: err,
	}
}

func (p *Parser) SkipWhite() {
	for {
		r, err := p.readRune()
		if err != nil {
			return
		}
		if r == ';' {
			for {
				r, err = p.readRune()
				if err != nil {
					return
				}
				if r == '\n' {
					break
				}
			}
			continue
		}
		if !unicode.IsSpace(r) {
			p.unreadRune()
			return
		}
	}
}

func (p *Parser) ParseParen(bq bool) (*Node, error) {
	first := true
	head := &amp;Node{
		t: NodeCell,
	}
	curr := head
	for {
		p.SkipWhite()
		b, err := p.buf.Peek(1)
		if err == io.EOF || (len(b) &gt; 0 &amp;&amp; b[0] == ')') {
			break
		}
		quote := err == nil &amp;&amp; b[0] == ','
		if quote {
			p.buf.ReadByte()
		}

		child, err := p.ParseAny(false)
		if err != nil {
			return nil, err
		}
		if child == nil {
			break
		}
		if bq &amp;&amp; !quote {
			child = &amp;Node{
				t:   NodeQuote,
				car: child,
			}
		}

		if child.t == NodeIdent &amp;&amp; child.v.(string) == "." &amp;&amp; !first {
			child, err = p.ParseAny(false)
			if err != nil {
				return nil, err
			}
			curr.cdr = child
			break
		} else if head.car != nil {
			x := &amp;Node{
				t: NodeCell,
				car: &amp;Node{
					t: NodeNil,
				},
			}
			curr.cdr = x
			curr = x
		}
		first = false
		curr.car = child
	}
	if head.car == nil &amp;&amp; head.cdr == nil {
		head.t = NodeNil
	}

	return head, nil
}

func (p *Parser) ParseString() (*Node, error) {
	var buf bytes.Buffer
	for {
		r, err := p.readRune()
		if err != nil {
			if err == io.EOF {
				break
			}
			return nil, err
		}

		if r == '\\' {
			r, err = p.readRune()
			if err != nil {
				return nil, err
			}
			switch r {
			case '\\':
				r = '\\'
			case 'n':
				r = '\n'
			case 'r':
				r = '\r'
			case 't':
				r = '\t'
			case 'b':
				r = '\b'
			case 'f':
				r = '\f'
			case '"':
				buf.WriteRune(r)
				continue
			}
		}
		if r == '"' {
			break
		}
		buf.WriteRune(r)
	}
	return &amp;Node{
		t: NodeString,
		v: buf.String(),
	}, nil
}

func (p *Parser) ParseArray() (*Node, error) {
	head := &amp;Node{
		t: NodeArray,
	}
	curr := head
	for {
		p.SkipWhite()
		b, err := p.buf.Peek(1)
		if err == io.EOF {
			break
		}
		if len(b) &gt; 0 &amp;&amp; b[0] == ']' {
			p.readRune()
			break
		}
		child, err := p.ParseAny(false)
		if err != nil {
			return nil, err
		}
		if child == nil {
			break
		}
		if head.car != nil {
			x := &amp;Node{
				t: NodeCell,
				car: &amp;Node{
					t: NodeNil,
				},
			}
			curr.cdr = x
			curr = x
		}
		curr.car = child
	}
	if head.car == nil &amp;&amp; head.cdr == nil {
		head.t = NodeNil
	}
	return head, nil
}

func (p *Parser) ParseQuote() (*Node, error) {
	node, err := p.ParseAny(false)
	if err != nil {
		return nil, err
	}
	return &amp;Node{
		t:   NodeQuote,
		car: node,
	}, nil
}

func (p *Parser) ParseBquote() (*Node, error) {
	node, err := p.ParseAny(true)
	if err != nil {
		return nil, err
	}
	return &amp;Node{
		t:   NodeBquote,
		car: node,
	}, nil
}
func isSymbolLetter(r rune) bool {
	return strings.ContainsRune(`+-*/&lt;&gt;=&amp;%?.@_#$:*`, r)
}

func (p *Parser) Pos() int {
	return p.pos
}

func (p *Parser) readRune() (rune, error) {
	r, n, err := p.buf.ReadRune()
	p.pos += n
	return r, err
}

func (p *Parser) unreadRune() error {
	err := p.buf.UnreadRune()
	p.pos -= 1
	return err
}

func (p *Parser) ParsePrimitive() (*Node, error) {
	var buf bytes.Buffer
	for {
		r, err := p.readRune()
		if err != nil {
			if err == io.EOF {
				break
			}
			return nil, err
		}

		if !unicode.IsLetter(r) &amp;&amp; !unicode.IsDigit(r) &amp;&amp; !isSymbolLetter(r) {
			p.unreadRune()
			break
		}
		buf.WriteRune(r)
	}

	s := buf.String()

	if s == "nil" {
		return &amp;Node{
			t: NodeNil,
			v: nil,
		}, nil
	}
	if s == "t" {
		return &amp;Node{
			t: NodeT,
			v: true,
		}, nil
	}
	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
		return &amp;Node{
			t: NodeInt,
			v: i,
		}, nil
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return &amp;Node{
			t: NodeDouble,
			v: f,
		}, nil
	}
	return &amp;Node{
		t: NodeIdent,
		v: s,
	}, nil
}

func (p *Parser) ParseAny(bq bool) (*Node, error) {
	p.SkipWhite()
	r, err := p.readRune()
	if err != nil {
		return nil, err
	}

	if r == '(' {
		node, err := p.ParseParen(bq)
		if err != nil {
			return nil, err
		}
		r, err := p.readRune()
		if err != nil || r != ')' {
			return nil, EOF
		}
		return node, nil
	}
	if unicode.IsLetter(r) || unicode.IsDigit(r) || isSymbolLetter(r) {
		p.unreadRune()
		return p.ParsePrimitive()
	}
	if r == '[' {
		return p.ParseArray()
	}
	if r == '\'' {
		return p.ParseQuote()
	}
	if r == '`' {
		return p.ParseBquote()
	}
	if r == '"' {
		return p.ParseString()
	}
	return nil, fmt.Errorf("invalid token: '%c' (%d)", r, p.Pos())
}

func (p *Parser) Parse() (*Node, error) {
	return p.ParseAny(false)
}

